def kthSmallestPairSum(nums, k):
    a = sorted(nums)
    n = len(a)

    def count_at_most(x):
        total = 0
        j = n - 1
        for i in range(n - 1):
            while j > i and a[i] + a[j] > x:
                j -= 1
            if j <= i:
                break
            total += j - i
        return total

    lo, hi = a[0] + a[1], a[-1] + a[-2]
    while lo < hi:
        mid = (lo + hi) // 2
        if count_at_most(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
